{
  "probability": 0.86,
  "range_low": 0.78,
  "range_high": 0.94,
  "summary": [
    "Bayesian posterior assigns 86% probability that CDU wins the most seats in Baden-Württemberg's 2026 Landtag election based on the available forecast evidence.",
    "Late-February polls show CDU leading Greens by a small margin, supporting CDU as most seats, though Greens are approaching parity.",
    "Historical patterns show Greens won the largest share in 2016 and 2021, which tempers certainty and justifies a calibrated uncertainty range.",
    "The Baden-Württemberg two-vote MMP system and turnout dynamics add translation risk from vote shares to seats, keeping the outcome non-guaranteed."
  ],
  "confidence": "high",
  "narrative": "Current credible polls place CDU ahead in Baden-Württemberg, and the pace of Greens' momentum plus historical deviations imply a high but not absolute chance of CDU securing the most seats. Under a two-vote MMP system with turnout effects, the probability is calibrated to 86% with a range reflecting policy- and polling-driven uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Historical Baden-Württemberg patterns: CDU has been largest in most elections (1952-2011) with Greens leading only in 2016 and 2021; this base rate is used as the prior anchor before updates from late-February polls and system dynamics."
    },
    "factor_updates": [
      {
        "factor": "Late-February polling lead for CDU",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Multiple polls show CDU around 28% vs Greens ~27%, sustaining a CDU edge that supports the expectation of CDU winning the most seats."
      },
      {
        "factor": "Greens closing the gap in late Feb polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens rising into low-to-mid 20s narrows CDU's edge and modestly lowers the probability of CDU securing a seat lead."
      },
      {
        "factor": "Two-vote MMP system and coalition dynamics",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "System effects can distort vote-to-seat translation and open coalition scenarios, introducing uncertainty about seat counts."
      },
      {
        "factor": "Historical pattern: Greens led in 2016 and 2021",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Past Greens-led outcomes show CDU's lead is not guaranteed, justifying a calibrated posterior below 1."
      },
      {
        "factor": "AfD and other small parties presence",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Nontrivial share can siphon votes and add seat-churn, but the net effect on CDU's lead is uncertain."
      }
    ],
    "synthesis_rationale": "Starting from a moderate base anchor, updates from late-February polls pushing CDU ahead while Greens close the gap, combined with structural system effects and historical deviations, yield a posterior around 0.86. The range incorporates translation uncertainty and potential turnout shifts; no single factor fully overrides others, so a calibrated interval is warranted."
  }
}

